<?php
declare(strict_types=1);
require_once __DIR__.'/../app/bootstrap.php';
use WexaShelf\{Database,Repository,CatalogQuery,Translations,Validation};
if($argc!==3)throw new RuntimeException('Usage: php php/tests/catalog-scale.php QA_DATABASE_JSON RESULT_JSON');
$config=json_decode(file_get_contents($argv[1]),true,512,JSON_THROW_ON_ERROR);if(!isset($config['database']))$config=['database'=>$config];$config['database']['name']='wexashelf_catalog_scale_070';$db=Database::connect($config);Database::migrate($db);$repo=new Repository($db,$config);$index=new CatalogQuery($db,$repo);$seed=json_decode(file_get_contents(__DIR__.'/../resources/seed.json'),true,512,JSON_THROW_ON_ERROR);$repo->seed($seed);$config['localization']=(new Translations($db,$repo))->settings();
$source=$repo->record('app','notion');$source['sourceLocale']='en';foreach(['plans','facts','storeMetrics','storeIds','storeLinks']as$key)$source['data'][$key]=[];$source['data']['platforms']=['android','ios','windows'];$source['admissionException']='Synthetic benchmark fixture';$source['seoApproved']=false;$source['status']='published';$source['revision']=1;Validation::managed($source);
$insert=$db->prepare('INSERT INTO ws_records(kind,id,payload) VALUES(?,?,?) ON DUPLICATE KEY UPDATE payload=VALUES(payload)');$results=[];$last=0;
foreach([10000,50000]as$size){$start=microtime(true);$db->beginTransaction();try{for($i=$last;$i<$size;$i++){$r=$source;$r['id']=$r['data']['id']='scale-'.str_pad((string)$i,6,'0',STR_PAD_LEFT);$r['data']['name']='Synthetic application '.$i;$r['data']['tags']=['scale-fixture','group-'.($i%20)];$r['data']['aliases']=['sample-'.$i];$r['data']['pricingModel']=$i%2?'free':'freemium';$insert->execute(['app',$r['id'],json_encode($r,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);} $db->commit();}catch(Throwable$e){$db->rollBack();throw$e;}$index->rebuild();$setup=microtime(true)-$start;
 $cases=['first-page'=>['q'=>'synthetic'],'deep-page'=>['q'=>'synthetic','page'=>(int)ceil($size/24)],'specific-search'=>['q'=>'sample-'.($size-1)],'filters'=>['tag'=>'group-7','pricing'=>'free','platform'=>'android,ios','mode'=>'all'],'missing'=>['q'=>'not-in-this-synthetic-catalog']];$measurements=[];
 foreach($cases as$name=>$input){$times=[];for($n=0;$n<7;$n++){$start=microtime(true);$page=$index->response(['locale'=>'en']+$input,$config);$times[]=(microtime(true)-$start)*1000;}sort($times);$measurements[$name]=['total'=>$page['total'],'returned'=>count($page['items']),'medianMs'=>round($times[3],2),'p95Ms'=>round($times[6],2),'jsonBytes'=>strlen(json_encode($page,JSON_THROW_ON_ERROR))];if(count($page['items'])>24)throw new RuntimeException('Unbounded response');}
 $start=microtime(true);$snapshot=$index->forPage('/en',[]);$result=['syntheticApps'=>$size,'setupSeconds'=>round($setup,2),'queries'=>$measurements,'homepage'=>['milliseconds'=>round((microtime(true)-$start)*1000,2),'apps'=>count($snapshot['apps']),'records'=>count($snapshot['records']),'jsonBytes'=>strlen(json_encode($snapshot,JSON_THROW_ON_ERROR))],'peakMemoryBytes'=>memory_get_peak_usage(true)];$results[]=$result;echo json_encode($result,JSON_THROW_ON_ERROR)."\n";$last=$size;
}
file_put_contents($argv[2],json_encode(['at'=>gmdate('c'),'database'=>'MariaDB local Docker','scope'=>'Synthetic database/API/snapshot benchmark; not Lighthouse, cPanel or production field performance.','results'=>$results],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n");
